PRAGMA foreign_keys=ON; CREATE TABLE ai_runs(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,status TEXT NOT NULL,provider_session_id TEXT,input_json TEXT NOT NULL,output_json TEXT,error TEXT,created_at TEXT NOT NULL,finished_at TEXT); CREATE TABLE ai_run_steps(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES ai_runs(id),kind TEXT NOT NULL,status TEXT NOT NULL,usage_units INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL); CREATE TABLE ai_balances(user_id TEXT PRIMARY KEY,balance INTEGER NOT NULL CHECK(balance>=0)); CREATE TABLE ai_usage(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES ai_runs(id),user_id TEXT NOT NULL,units INTEGER NOT NULL CHECK(units>=0),policy_version TEXT NOT NULL,created_at TEXT NOT NULL);
